/**
 * SKB shared domain types.
 *
 * Conventions:
 *  - Monetary amounts are integers in **minor units** (e.g. piastres/cents). Never floats.
 *  - IDs are opaque strings (UUIDs) generated by the server.
 *  - Timestamps are ISO‑8601 strings when serialized over the wire.
 */

import type { ChargeKind } from './charges';

// ---------------------------------------------------------------------------
// Locale & presentation
// ---------------------------------------------------------------------------

export type Locale = 'en' | 'ar';
export type Direction = 'ltr' | 'rtl';
export type ThemeMode = 'light' | 'dark' | 'system';

/** Device class the adaptive shell renders for. */
export type DeviceClass = 'phone' | 'tablet' | 'desktop';
export type Platform = 'ios' | 'android' | 'windows' | 'macos' | 'web';

// ---------------------------------------------------------------------------
// Identity, roles & permissions
// ---------------------------------------------------------------------------

/** Coarse roles. Fine‑grained gating is done with Permission below. */
export type Role = 'OWNER' | 'ADMIN' | 'ACCOUNTANT' | 'SALES' | 'INVENTORY' | 'VIEWER';

export const ROLES: readonly Role[] = [
  'OWNER',
  'ADMIN',
  'ACCOUNTANT',
  'SALES',
  'INVENTORY',
  'VIEWER',
] as const;

