// ---------------------------------------------------------------------------
// Cheques & promissory notes (DOMAIN.md §2.7)
// ---------------------------------------------------------------------------

export type NoteKind = 'CHEQUE' | 'PROMISSORY_NOTE';
/** RECEIVABLE: we hold it and collect it. PAYABLE: we issued it and pay it. */
export type NoteDirection = 'RECEIVABLE' | 'PAYABLE';
export type NoteStatus =
  | 'IN_HAND'
  | 'UNDER_COLLECTION'
  | 'COLLECTED'
  | 'BOUNCED'
  | 'ENDORSED'
  | 'CANCELLED'
  | 'ISSUED'
  | 'PAID'
  /** Lost or stolen (owner, 2026-10-02): the party owes again, as on a bounce. */
  | 'LOST';

export interface NoteEvent {
  fromStatus: NoteStatus | null;
  toStatus: NoteStatus;
  accountName: string | null;
  partyName: string | null;
  remark: string | null;
  staffName: string;
  createdAt: string;
}

export interface Note {
  id: string;
  /** Our reference, NR-… or NP-…. */
  ref: string;
  kind: NoteKind;
  direction: NoteDirection;
  status: NoteStatus;
  /** The number printed on the cheque / note. */
  serialNumber: string;
  bankName: string | null;
  amount: number;
  /** yyyy-mm-dd. */
  dueDate: string;
  /** Past due and still open. */
  overdue: boolean;
  drawer: string | null;
  guarantor: string | null;
  partyId: string;
  partyName: string;
  endorsedToName: string | null;
  branchName: string;
  portfolioNumber: string | null;
  accountId: string | null;
  accountName: string | null;
  remark: string | null;
  createdAt: string;
  createdByName: string;
  allocations: { documentId: string; number: string; amount: number }[];
  events: NoteEvent[];
  currency: string;
  /** The day it came (or was handed over), yyyy-mm-dd, and who brought (or took) it. */
  receivedOn?: string | null;
  broughtBy?: string | null;
  /** A photo of the paper is kept (GET /notes/{id}/photo). */
  hasPhoto?: boolean;
  partyCode?: number | null;
}

/** A batch of notes lodged at a bank (حافظة). */
export interface Portfolio {
  id: string;
  number: string;
  accountName: string;
  branchName: string;
  createdAt: string;
  createdByName: string;
  count: number;
  total: number;
  refs: string[];
  currency: string;
}

export interface NotesSummary {
  receivableOpen: number;
  receivableOverdue: number;
  receivableDueWeek: number;
  payableOpen: number;
  payableOverdue: number;
  payableDueWeek: number;
  currency: string;
}

